<script setup lang="ts">
import {CopyDocument} from '@element-plus/icons-vue'
import {ElMessage} from 'element-plus'

type ValidationItem={id:string;title:string;kind:string;state:string;status:string;summary:string;exitCode?:number;duration?:number;command:string;parameters:string;raw:string}
type ValidationDetail={title:string;kind:string;state:string;status:string;summary:string;exitCode?:number;duration?:number;count:number;items:ValidationItem[]}
const props=defineProps<{detail:ValidationDetail;expanded?:boolean}>()
const emit=defineEmits<{close:[];toggleExpand:[]}>()
async function copy(){
 const value=props.detail.items.map((item,index)=>[props.detail.count>1?`第 ${index+1} 项`:'',item.command?`执行命令\n${item.command}`:item.parameters?`执行参数\n${item.parameters}`:'',`原始输出\n${item.raw||'无输出'}`].filter(Boolean).join('\n\n')).join('\n\n----------------\n\n')
 try{await navigator.clipboard.writeText(value);ElMessage.success('已复制验证详情')}catch(error){ElMessage.error(String(error))}
}
</script>

<template>
 <aside class="validation-detail-pane" :class="{expanded}" role="region" :aria-label="`${detail.title}验证详情`">
  <header><div><strong>{{detail.title}}</strong><span>{{detail.kind}}<template v-if="detail.count>1"> · {{detail.count}} 项</template></span></div><button title="复制详情" aria-label="复制验证详情" @click="copy"><CopyDocument/></button><button :title="expanded?'缩小到右侧':'展开详情区域'" :aria-label="expanded?'缩小到右侧':'展开详情区域'" @click="emit('toggleExpand')"><svg v-if="!expanded" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 4H4v5M15 20h5v-5M4 4l6 6m10 10-6-6"/></svg><svg v-else viewBox="0 0 24 24" aria-hidden="true"><path d="M10 10H5V5m9 9h5v5M5 10l5-5m9 9-5 5"/></svg></button><button class="panel-toggle" title="关闭详情" aria-label="关闭验证详情" @click="emit('close')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button></header>
  <div class="validation-detail-body">
   <section class="validation-detail-summary"><span class="validation-detail-status" :class="detail.state">{{detail.status}}</span><div><strong>{{detail.summary}}</strong><small><template v-if="detail.exitCode!==undefined">退出码 {{detail.exitCode}}</template><template v-if="detail.duration!==undefined"> · 用时 {{(detail.duration/1000).toFixed(1)}} 秒</template></small></div></section>
   <article v-for="(item,index) in detail.items" :key="item.id" class="validation-detail-item"><header v-if="detail.count>1"><strong>第 {{index+1}} 项</strong><span>{{item.duration===undefined?'未记录耗时':(item.duration/1000).toFixed(1)+' 秒'}}<template v-if="item.exitCode!==undefined"> · 退出码 {{item.exitCode}}</template></span></header><section v-if="item.command||item.parameters"><h3>{{item.command?'执行命令':'执行参数'}}</h3><pre>{{item.command||item.parameters}}</pre></section><section><h3>原始输出</h3><pre>{{item.raw||'无输出'}}</pre></section></article>
  </div>
 </aside>
</template>

<style scoped>
