on-detail-item:last-child{margin-bottom:0;border-bottom:0}.validation-detail-item>header{display:flex;align-items:center;justify-content:space-between;margin:0 0 12px}.validation-detail-item>header strong{font-size:12px}.validation-detail-item>header span{color:#82958a;font-size:10px}.validation-detail-item>section+section{margin-top:15px}.validation-detail-body h3{margin:0 0 8px;color:#82958a;font-size:11px;font-weight:600}.validation-detail-body pre{max-height:50vh;overflow:auto;margin:0;padding:12px;border:1px solid #29352f;border-radius:8px;background:#0d1410;color:#cdd8d1;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.7 'SFMono-Regular',Consolas,'Microsoft YaHei UI',monospace}@container studio (max-width:1000px){.validation-detail-pane{width:50%;min-width:340px}}@container studio (max-width:700px){.validation-detail-pane{position:absolute;inset:0 0 0 auto;z-index:30;width:100%;min-width:0}.validation-detail-pane.expanded{width:100%}}
